    license: "",
    referenceFiles: ["beats.md", "cloud.md", "cloudrun.md", "compare-and-batch.md", "doctor-browser.md", "init-and-scaffold.md", "lambda.md", "lint-validate-inspect.md", "preview-render.md", "upgrade-info-misc.md"],
    source: "https://github.com/heygen-com/hyperframes.git",
