    referenceFiles: ["composition-patterns.md", "creator-editing-recipes.md", "data-attributes.md", "determinism-rules.md", "full-screen-motion.md", "minimal-composition.md", "sub-compositions.md", "tailwind.md", "tracks-and-clips.md", "variables-and-media.md"],
    source: "https://github.com/heygen-com/hyperframes.git",
